declare class GraphNode {
  val: number
  neighbors: GraphNode[]
  constructor(val?: number, neighbors?: GraphNode[])
}

function cloneGraph(node: GraphNode | null): GraphNode | null {
  if (!node) return null
  const copies = new Map<GraphNode, GraphNode>()
  function copy(n: GraphNode): GraphNode {
    const existing = copies.get(n)
    if (existing) return existing
    const clone = new GraphNode(n.val)
    copies.set(n, clone)
    for (const nb of n.neighbors) clone.neighbors.push(copy(nb))
    return clone
  }
  return copy(node)
}
